{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-tabs.json
    Features behind a tab list: the chosen tab shows its text and a picture. The page keeps the chosen tab (`active`, empty for the first) and updates it on the `select` event. Axes: panel (split: text beside the picture, stack: picture below), tone, density.
    Props (p): id, title, features, empty, tabsLabel, active, panel, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_features = ($p['features'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_tabsLabel = ($p['tabsLabel'] ?? null)}
{var $v_active = ($p['active'] ?? '')}
{var $v_panel = ($p['panel'] ?? 'split')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_8}
  {if og_t(og_eq(og_len($v_features), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'layout-grid', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_7}
      {capture $c_2}
        {foreach og_l($v_features) as $v_f}
          {var $v_i = $iterator->counter0}
          {capture $c_1}
            {=og_text(og_get($v_f, ['title']))}
          {/capture}
          {=og_include('blocks/switcher-item.latte', ['p' => ['active' => og_or([og_eq(og_get($v_f, ['id']), $v_active), og_and([og_eq($v_active, ''), og_eq($v_i, 0)])])], 'children' => og_markup($c_1)])|noescape}
        {/foreach}
      {/capture}
      {=og_include('blocks/switcher.latte', ['p' => ['label' => $v_tabsLabel, 'className' => og_cnv(['w-fit max-w-full flex-wrap'])], 'children' => og_markup($c_2)])|noescape}
      {foreach og_l($v_features) as $v_f}
        {var $v_i = $iterator->counter0}
        {if og_t(og_or([og_eq(og_get($v_f, ['id']), $v_active), og_and([og_eq($v_active, ''), og_eq($v_i, 0)])]))}
          {capture $c_6}
            {capture $c_5}
              {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_f, ['icon'])), 'size' => 24])|noescape}
              {capture $c_3}
                {=og_text(og_get($v_f, ['title']))}
              {/capture}
              {=og_include('compose/Title.latte', ['as' => 3, 'size' => '2xl', 'weight' => 'bold', 'children' => (string) $c_3])|noescape}
              {capture $c_4}
                {=og_text(og_get($v_f, ['text']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'base', 'class' => 'text-muted-foreground', 'children' => (string) $c_4])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '4', 'children' => (string) $c_5])|noescape}
            {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_f, ['title']), 'ratio' => '4/3']])|noescape}
          {/capture}
          {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_panel, 'split')) ? '1-2' : '1')), 'class' => 'items-center gap-8', 'attrs' => og_attrs(['data-testid', 'tab-panel', 'role', 'tabpanel']), 'children' => (string) $c_6])|noescape}
        {/if}
      {/foreach}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '6', 'align' => 'stretch', 'children' => (string) $c_7])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_8)])|noescape}
